package com.biblioteca.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;

import java.util.ArrayList;
import java.util.List;

/** Represents a row of the "livro" (book) table. */
@Entity
@Table(name = "livro")
public class Livro {

    // IDENTITY = the id is generated by the database column (SERIAL / IDENTITY),
    // exactly like before, when the JDBC code asked the driver for the generated key.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    private int id;

    @Column(name = "titulo")
    private String titulo;

    @Column(name = "autor")
    private String autor;

    @Column(name = "ano_publicacao")
    private int anoPublicacao;

    @Column(name = "disponivel")
    private boolean disponivel;

    // Inverse side of Emprestimo.livro (the foreign key lives in the "emprestimo" table).
    // No cascade on purpose: deleting a book that still has loans must keep being refused
    // by the database (foreign key violation), as it was with plain JDBC.
    @OneToMany(mappedBy = "livro")
    private List<Emprestimo> emprestimos = new ArrayList<>();

    public Livro() {
    }

    // Convenient constructor for a new book (the id is generated by the database).
    public Livro(String titulo, String autor, int anoPublicacao, boolean disponivel) {
        this.titulo = titulo;
        this.autor = autor;
        this.anoPublicacao = anoPublicacao;
        this.disponivel = disponivel;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getTitulo() {
        return titulo;
    }

    public void setTitulo(String titulo) {
        this.titulo = titulo;
    }

    public String getAutor() {
        return autor;
    }

    public void setAutor(String autor) {
        this.autor = autor;
    }

    public int getAnoPublicacao() {
        return anoPublicacao;
    }

    public void setAnoPublicacao(int anoPublicacao) {
        this.anoPublicacao = anoPublicacao;
    }

    public boolean isDisponivel() {
        return disponivel;
    }

    public void setDisponivel(boolean disponivel) {
        this.disponivel = disponivel;
    }

    public List<Emprestimo> getEmprestimos() {
        return emprestimos;
    }

    public void setEmprestimos(List<Emprestimo> emprestimos) {
        this.emprestimos = emprestimos;
    }

    @Override
    public String toString() {
        return "Livro{id=" + id
                + ", titulo='" + titulo + '\''
                + ", autor='" + autor + '\''
                + ", anoPublicacao=" + anoPublicacao
                + ", disponivel=" + disponivel + '}';
    }
}
